CREATE TABLE IF NOT EXISTS agent_health (server_id varchar(36) NOT NULL PRIMARY KEY REFERENCES servers(id), collector_state varchar(16) NOT NULL DEFAULT 'unknown', collector_message varchar(256) NOT NULL DEFAULT '', state_since timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, queue_depth integer NOT NULL DEFAULT 0, rejected_events integer NOT NULL DEFAULT 0, last_poll_at timestamp, last_event_at timestamp, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_channels (id varchar(36) NOT NULL PRIMARY KEY, name varchar(128) NOT NULL, kind varchar(16) NOT NULL, config_ciphertext text NOT NULL, last_attempt_at timestamp, enabled boolean NOT NULL DEFAULT true, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alert_rules (id varchar(36) NOT NULL PRIMARY KEY, name varchar(128) NOT NULL, kind varchar(32) NOT NULL, enabled boolean NOT NULL DEFAULT true, threshold_count integer NOT NULL DEFAULT 5, window_seconds integer NOT NULL DEFAULT 300, cooldown_seconds integer NOT NULL DEFAULT 300, server_group varchar(64) NOT NULL DEFAULT '', trusted_cidrs text NOT NULL, channel_ids text NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alerts (id varchar(36) NOT NULL PRIMARY KEY, rule_id varchar(36), server_id varchar(36) REFERENCES servers(id), event_id varchar(36), severity varchar(16) NOT NULL, title varchar(256) NOT NULL, message text NOT NULL, acknowledged_by varchar(36) REFERENCES users(id), acknowledged_at timestamp, resolved_at timestamp, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS alerts_time ON alerts(created_at);
CREATE INDEX IF NOT EXISTS alerts_server ON alerts(server_id,created_at);
CREATE TABLE IF NOT EXISTS alert_state (state_key varchar(64) NOT NULL PRIMARY KEY, last_alert_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS notification_jobs (id varchar(36) NOT NULL PRIMARY KEY, alert_id varchar(36) NOT NULL REFERENCES alerts(id), channel_id varchar(36) NOT NULL REFERENCES notification_channels(id), status varchar(16) NOT NULL DEFAULT 'pending', priority integer NOT NULL DEFAULT 0, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamp NOT NULL, locked_until timestamp, lease_token varchar(64) NOT NULL DEFAULT '', last_error varchar(512) NOT NULL DEFAULT '', sent_at timestamp, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS jobs_due ON notification_jobs(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS jobs_alert ON notification_jobs(alert_id);
INSERT INTO alert_rules(id,name,kind,threshold_count,window_seconds,cooldown_seconds,trusted_cidrs,channel_ids) SELECT '00000000-0000-4000-8000-000000000001','SSH 登录成功','login',1,300,60,'[]','[]' WHERE NOT EXISTS (SELECT 1 FROM alert_rules WHERE id='00000000-0000-4000-8000-000000000001');
